import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t,P as n,q as o}from"./D3cAVrQp.js";const a={title:"Technology Governance Framework",subtitle:"Technology Risk, Public-Interest Standards, Community Self-Determination, and Lawful Intervention",version:3.6,status:"Constitutional alignment revision and pilot-design basis",tier:"1 — Constitutional and Cross-Domain Interface",revision_date:"2026-08-01T00:00:00.000Z",supersedes:"Technology Governance Implementation Framework v3.5"},{title:d,subtitle:u,version:p,status:h,tier:m,revision_date:y,supersedes:g}=a;var r=t("<h1>Technology Governance Framework v3.6</h1> <h2>Technology Risk, Public-Interest Standards, Community Self-Determination, and Lawful Intervention</h2> <h3>Related frameworks</h3> <ul><li><strong>Aurora Accord</strong> — data rights, identity, fiduciary duties, and federated data stewardship</li> <li><strong>Justice Systems Framework</strong> — due process, adjudication, remedy, and enforcement interfaces</li> <li><strong>The Synoptic Protocol</strong> — information-system accountability, recommender scope, and epistemic rights</li> <li><strong>AUBI Framework</strong> — material security, epistemic rights, and non-deprivation floors</li> <li><strong>Work in Liberation Framework</strong> — labour justice, maintenance work, and technological transition</li> <li><strong>Integrated Meta-Governance Framework</strong> — cross-domain coordination and institutional dispute resolution</li> <li><strong>Genesis Protocol</strong> — pre-constitutional preparation, pilots, first seating, and authority provenance</li> <li><strong>Treaty for Our Only Home</strong> — Treaty jurisdiction, institutions, enforcement, and emergency authority</li> <li><strong>Constitutional Interface Specification</strong> — plural legitimacy, decision classes, observation, and framework authority boundaries</li> <li><strong>Indigenous Sovereignty and Planetary Healing</strong> — Indigenous authority, consent, protected knowledge, and non-certification</li></ul> <h3>Version history</h3> <ul><li><strong>Editorial edition (2026-08-02).</strong> No substantive change. Added this version history and a related-frameworks section, neither of which the document previously had; the v3.6 entry below is reconstructed from the framework’s own executive summary and earlier entries remain to be recorded. Removed version pins from body prose so that a reference names an instrument rather than asserting a live dependency that goes stale when another framework moves; editions consulted are recorded here instead. Editions consulted: Aurora Accord v1.3; Justice Systems Framework v1.4; The Synoptic Protocol v4.2; AUBI v2.5; Work in Liberation v2.0; Integrated Meta-Governance v1.5; Genesis Protocol v0.9; Treaty for Our Only Home v1.3; Constitutional Interface Specification v0.1; Indigenous Sovereignty and Planetary Healing v1.1.</li> <li><strong>3.6 (2026-08-01):</strong> Constitutional alignment revision of the Technology Governance Implementation Framework v3.5. Preserved v3.5’s strongest commitments — technological refusal, digital disconnection, accessibility, neurodiversity, community review, cybersecurity resilience, lifecycle responsibility, labour justice, public-interest AI capacity, interoperability, repair, and funded open-source maintenance — while removing the integrated council, legal risk tiers, moral-pattern vetoes, automatic circuit breakers, universal Indigenous proxy, and certification-linked economic rewards. Established that governance attaches to a specified use, operator, population, place, dependency, infrastructure, decision, and possible harm rather than to technology as such. Separated seven functions: foresight and public-interest research; voluntary standards development; independent assessment and accreditation; domain-specific lawful regulation; community and affected-party review; bounded cybersecurity and incident coordination; and adjudication, remedy, and enforcement through competent institutions. Replaced the Technology Risk and Responsibility Tiering System with the multidimensional Technology Use, Dependency, and Impact Profile.</li> <li><strong>Earlier editions:</strong> not yet recorded in this document.</li></ul> <hr> <blockquote><p><strong>Governing principle:</strong> Technology Governance helps competent authorities and affected communities perceive technological risk, compare options, preserve refusal, and coordinate lawful action. It does not turn its own model of technological sanity into authority over technology or society.</p></blockquote> <hr> <h1>Executive summary</h1> <p>Technology shapes what people can perceive, access, repair, refuse, own, share, and become. It can support ecological restoration, public learning, disability access, community autonomy, and distributed prosperity. It can also centralize surveillance, make participation compulsory, manipulate attention, automate exclusion, obscure responsibility, externalize ecological costs, and create dependencies that are difficult to leave.</p> <p>This framework provides a cross-domain architecture for governing those effects without creating a universal technology regulator. It preserves the strongest commitments of Technology Governance v3.5—technological refusal, digital disconnection, accessibility, neurodiversity, community review, cybersecurity resilience, lifecycle responsibility, labour justice, public-interest AI capacity, interoperability, repair, and funded open-source maintenance—while replacing the former integrated council, legal risk tiers, moral-pattern vetoes, automatic circuit breakers, universal Indigenous proxy, and certification-linked economic rewards.</p> <p>The framework does <strong>not</strong> govern “technology as such.” Governance attaches to a specified use, operator, population, place, dependency, infrastructure, decision, and possible harm. The same technical artefact may be low-consequence in one use and legally consequential in another.</p> <p>No assessment, dashboard, certification, standard, AI output, satisfaction index, or ethical diagnosis creates legal authority. Compulsory intervention must derive from valid law, contract, public procurement authority, system ownership, judicial order, Indigenous authority within its jurisdiction, or another independently valid instrument. Justice, sanctions, injunctions, and remedies follow the Justice Systems Framework. Data, identity, telemetry, records, and AI-training data follow the Aurora Accord. Treaty activation and first seating follow Genesis Protocol.</p> <p>The framework separates seven functions:</p> <ol><li>foresight and public-interest research;</li> <li>voluntary standards development;</li> <li>independent assessment and accreditation;</li> <li>domain-specific lawful regulation;</li> <li>community and affected-party review;</li> <li>bounded cybersecurity and incident coordination;</li> <li>adjudication, remedy, and enforcement through competent institutions.</li></ol> <p>The former Technology Risk & Responsibility Tiering System is replaced by a multidimensional <strong>Technology Use, Dependency, and Impact Profile</strong>. The profile records evidence and uncertainty across bodily, social, cognitive, ecological, labour, data, security, concentration, reversibility, Indigenous-rights, essential-service, and cross-boundary dimensions. It does not collapse those dimensions into one legal tier.</p> <p>The framework’s intervention rule is:</p> <blockquote><p><strong>An assessment may justify attention, testing, negotiation, a recommendation, or a request to a competent authority. It does not by itself justify a moratorium, shutdown, sanction, redistribution, emergency, or compulsory redesign.</strong></p></blockquote> <hr> <h1>1. Purpose, status, and non-authority</h1> <h2>1.1 Purpose</h2> <p>This framework supports lawful, plural, and anticipatory governance of technologies whose effects cross jurisdictions, infrastructures, communities, and sectors. It provides reusable assessment methods, interface records, public-interest standards, participation safeguards, and handoff procedures.</p> <h2>1.2 Status</h2> <p>This is a framework for constitutional and operational alignment. It is not, by itself, a statute, treaty, licence, permit, court order, certification mandate, emergency declaration, procurement rule, or technical command.</p> <h2>1.3 Non-authority clause</h2> <p>The framework does not itself:</p> <ul><li>legislate or create offences;</li> <li>create jurisdiction over a technology, developer, operator, community, or user;</li> <li>issue compulsory classifications, licences, certifications, moratoria, recalls, shutdowns, or trade restrictions;</li> <li>declare or extend an emergency;</li> <li>redistribute money, compute, intellectual property, data, or ownership;</li> <li>represent Indigenous peoples or certify Indigenous consent;</li> <li>determine psychological sanity, intelligence, truth, developmental worth, or valid dissent;</li> <li>adjudicate liability or impose sanctions;</li> <li>authorize surveillance, evidence seizure, detention, armed action, or cyber operations;</li> <li>require Hearts, Leaves, AUBI, Love Ledger participation, or a universal digital identity.</li></ul> <p>Any consequential act requires an independently valid source of authority recorded in a <strong>Technology Authority Provenance Record</strong>.</p> <h2>1.4 No framework-to-law conversion</h2> <p>A GGF principle, assessment, standard, checklist, profile, or recommendation becomes legally binding only when a competent institution adopts it through valid law, regulation, contract, procurement condition, compact, permit, Indigenous authority, judicial order, or other lawful instrument.</p> <hr> <h1>2. Sources of authority and applicable law</h1> <h2>2.1 Recognized authority sources</h2> <p>A technology-governance action may derive from:</p> <ul><li>Treaty authority validly activated under Treaty;</li> <li>domestic, regional, municipal, or sectoral law;</li> <li>Indigenous law and authority within the relevant people’s jurisdiction;</li> <li>a lawful compact, charter, permit, licence, contract, procurement condition, or system-owner mandate;</li> <li>voluntary participation and informed agreement;</li> <li>a judicial or tribunal order issued under valid jurisdiction;</li> <li>emergency authority validly constituted outside this framework.</li></ul> <h2>2.2 Technology Authority Provenance Record</h2> <p>Before a consequential action, the acting body must identify:</p> <ul><li>the actor;</li> <li>the legal or contractual source of authority;</li> <li>the territorial, personal, functional, and temporal scope;</li> <li>the governed technology use;</li> <li>affected rights and populations;</li> <li>review and appeal routes;</li> <li>continuity protections;</li> <li>the date and condition on which authority expires.</li></ul> <p>No provenance record, no compulsory action.</p> <h2>2.3 Applicable-law conflicts</h2> <p>Where multiple legal orders may apply, the record must identify conflicts among Treaty law, domestic law, Indigenous law, sectoral regulation, contracts, and transnational standards. Meta-Governance may convene the competent actors and maintain the interface record. It may not decide the legal conflict.</p> <hr> <h1>3. Scope and governed-use description</h1> <h2>3.1 Governance attaches to use</h2> <p>The object of governance is not an abstract technology category. It is a <strong>governed use</strong> consisting of:</p> <ul><li>technical artefact or service;</li> <li>intended and reasonably foreseeable uses;</li> <li>operator and controlling entities;</li> <li>users and affected non-users;</li> <li>location and jurisdiction;</li> <li>scale and duration;</li> <li>data, compute, infrastructure, labour, and supply-chain dependencies;</li> <li>decision or action enabled;</li> <li>alternatives and refusal pathways;</li> <li>possible harms, benefits, and irreversible effects.</li></ul> <h2>3.2 Exclusions</h2> <p>The framework does not claim residual jurisdiction over a use merely because it involves software, AI, biotechnology, automation, networks, robotics, digital identity, or data. Domain-specific authorities retain their lawful competence.</p> <h2>3.3 Cross-domain interface</h2> <p>Technology Governance provides common documentation and coordination where one use implicates several frameworks—for example healthcare AI, automated labour management, ecological sensing, public-benefit allocation, autonomous transport, critical infrastructure, or security systems.</p> <hr> <h1>4. Technology modalities and decision classes</h1> <p>Governance must distinguish at least the following modalities:</p> <ol><li>research and laboratory exploration;</li> <li>model or product development;</li> <li>controlled testing and sandbox use;</li> <li>private consumer deployment;</li> <li>professional decision support;</li> <li>public-sector procurement;</li> <li>public-benefit or rights-affecting administration;</li> <li>essential-service operation;</li> <li>critical-infrastructure operation;</li> <li>employment and workplace management;</li> <li>education, childhood, and care settings;</li> <li>policing, border, intelligence, defence, or security use;</li> <li>ecological or planetary intervention;</li> <li>open-source publication and community maintenance;</li> <li>discontinuation, withdrawal, recall, migration, and decommissioning.</li></ol> <p>A use may move between modalities. Reassessment is required when the operator, scale, population, data, purpose, dependency, or legal authority materially changes.</p> <hr> <h1>5. Functional separation</h1> <h2>5.1 Foresight and research</h2> <p>Foresight bodies map emerging capabilities, dependencies, uncertainties, and possible harms. They may publish scenarios and research agendas. They do not issue binding orders.</p> <h2>5.2 Standards development</h2> <p>Standards bodies develop voluntary, transparent, technology-neutral specifications. Participation in drafting does not create regulatory authority.</p> <h2>5.3 Assessment and accreditation</h2> <p>Independent assessors evaluate evidence against a disclosed scope. Accreditation bodies evaluate assessors. Neither may adjudicate liability or impose public sanctions.</p> <h2>5.4 Lawful regulation</h2> <p>Regulators act only within their constituted domain and jurisdiction. They may adopt or reference standards, but must provide due process, proportionality, review, and appeal.</p> <h2>5.5 Community and affected-party review</h2> <p>Review boards document local conditions, exclusion, dependency, refusal, accessibility, labour, and cultural concerns. They may recommend, challenge, negotiate, or invoke locally valid authority. They do not automatically govern actors beyond their jurisdiction.</p> <h2>5.6 Cyber coordination</h2> <p>Incident coordinators support containment, recovery, evidence preservation, and lawful handoff. They do not become investigators, prosecutors, judges, or permanent emergency authorities merely because a cyber incident occurs.</p> <h2>5.7 Justice and enforcement</h2> <p>Courts, tribunals, regulators, and enforcement bodies act under Justice Systems and the law that creates their competence.</p> <hr> <h1>6. Technology Use, Dependency, and Impact Profile</h1> <h2>6.1 Replacement of TRRT</h2> <p>The Technology Risk & Responsibility Tiering System is retired as a universal legal classification. v3.6 uses a multidimensional profile that prevents one score from concealing trade-offs or manufacturing jurisdiction.</p> <h2>6.2 Required dimensions</h2> <p>The profile records, where relevant:</p> <ul><li>bodily safety and health;</li> <li>disability access and exclusion;</li> <li>children and dependent persons;</li> <li>data, identity, inference, and surveillance;</li> <li>cognitive influence, attention, persuasion, and autonomy;</li> <li>labour, livelihood, workplace power, and maintenance burden;</li> <li>ecological, energy, water, mineral, hardware, and waste impacts;</li> <li>cybersecurity, abuse, misuse, and dual-use potential;</li> <li>concentration of ownership, compute, standards, and infrastructure;</li> <li>essential-service and public-rights dependency;</li> <li>interoperability, portability, repair, and exit;</li> <li>reversibility, recoverability, and decommissioning;</li> <li>cross-border and cross-boundary effects;</li> <li>Indigenous territory, rights, knowledge, and authority;</li> <li>supply-chain and geopolitical dependencies;</li> <li>uncertainty, missing populations, and model limitations.</li></ul> <h2>6.3 No composite legal score</h2> <p>A profile may summarize but must not produce one authoritative moral, psychological, regulatory, or legal score. High concern in one dimension may require action under competent law even if aggregate benefits are large. Conversely, a poor overall score does not by itself authorize intervention.</p> <h2>6.4 Comparable alternatives</h2> <p>Assessments must include technically and institutionally realistic alternatives, including non-deployment, lower-tech provision, human service, local alternatives, open standards, and delayed adoption.</p> <hr> <h1>7. Risk evidence, state estimates, and uncertainty</h1> <h2>7.1 Observation Contract</h2> <p>Each consequential assessment must state:</p> <ul><li>the decision it is intended to inform;</li> <li>indicators and data sources;</li> <li>populations represented and missing;</li> <li>measurement limitations;</li> <li>update frequency;</li> <li>data-governance basis under Aurora;</li> <li>who may challenge or correct the record;</li> <li>prohibited secondary uses.</li></ul> <h2>7.2 State estimates</h2> <p>Risk is treated as an uncertain state estimate rather than a directly observed fact. Where feasible, assessments must publish competing interpretations, confidence, assumptions, and evidence that could change the conclusion.</p> <h2>7.3 Independence and conflicts</h2> <p>The <strong>Assessment Independence and Conflict Map</strong> discloses funders, vendors, operators, model providers, consultants, data suppliers, evaluators, affected institutions, and shared technical dependencies.</p> <h2>7.4 No required adverse finding</h2> <p>A pilot, audit, or evaluation need not identify a minimum number of harmful, extractive, addictive, biased, or “parasitic” technologies. The process must permit a finding of no material concern, insufficient evidence, or an incorrect original hypothesis.</p> <hr> <h1>8. Affected-party standing and participation</h1> <h2>8.1 Standing</h2> <p>Depending on the lawful process, standing may include:</p> <ul><li>users and affected non-users;</li> <li>workers, maintainers, contractors, and unions;</li> <li>children, caregivers, and representatives;</li> <li>disabled and neurodivergent persons;</li> <li>communities experiencing infrastructure or ecological burdens;</li> <li>public-service recipients;</li> <li>operators, developers, small enterprises, and open-source maintainers;</li> <li>ecological or future-generation representatives where validly constituted;</li> <li>affected Indigenous peoples through their own authorities;</li> <li>public-interest advocates authorized by law.</li></ul> <h2>8.2 Participation rights</h2> <p>Participants must have accessible notice, time, language support, disability accommodations, relevant evidence, response rights, representation where needed, and protection against retaliation.</p> <h2>8.3 No participation-by-telemetry</h2> <p>Behavioural tracking, sentiment analysis, productivity data, mental-health inference, or engagement metrics do not substitute for participation or consent.</p> <hr> <h1>9. Community technology self-determination</h1> <h2>9.1 Local Technology Sovereignty Charter</h2> <p>A community may adopt a lawful charter specifying:</p> <ul><li>technology uses it operates or procures;</li> <li>accessibility and refusal rules;</li> <li>local data and infrastructure boundaries;</li> <li>essential-service continuity;</li> <li>community review and complaint routes;</li> <li>interoperability and exit requirements;</li> <li>worker and maintainer protections;</li> <li>emergency and decommissioning procedures.</li></ul> <h2>9.2 Right to refuse and disconnect</h2> <p>No person should lose essential services, lawful status, education, healthcare, AUBI Layer 1, employment protections, justice access, or political rights solely for declining a non-essential digital channel. Equivalent non-digital or low-data routes must be provided where feasible and legally required.</p> <h2>9.3 Bounded community authority</h2> <p>A community may govern technology within its lawful jurisdiction and collective assets. It does not gain a universal veto over other communities or individual rights.</p> <h2>9.4 Non-digitization as a valid outcome</h2> <p>A review may conclude that a process, knowledge domain, community relationship, or public service should remain non-digital, local-only, or deliberately low-tech.</p> <hr> <h1>10. Indigenous technology interfaces</h1> <h2>10.1 Recognition, not creation</h2> <p>The framework does not create an Earth Council, universal Indigenous technology body, global veto proxy, or GGF certification of Indigenous authority.</p> <h2>10.2 Affected-nation authority</h2> <p>Technology affecting Indigenous territory, law, identity, culture, knowledge, sacred relations, resources, or community data requires an interface with the affected people’s own authorities and procedures.</p> <h2>10.3 Indigenous Technology Interface and Non-Engagement Record</h2> <p>The record may specify:</p> <ul><li>the affected people and authority identified by that people;</li> <li>applicable Indigenous and other law;</li> <li>consent, refusal, or non-engagement;</li> <li>protected knowledge and non-transfer;</li> <li>data, model-training, documentation, publication, and repatriation terms;</li> <li>benefit, labour, and ownership arrangements;</li> <li>monitoring, breach response, remedy, and exit;</li> <li>unresolved jurisdictional boundaries.</li></ul> <h2>10.4 No metric substitution</h2> <p>FPIC satisfaction, consultation counts, participation rates, or Indigenous representation percentages do not substitute for a valid decision by the affected people.</p> <hr> <h1>11. Accessibility, cognitive liberty, and non-discrimination</h1> <h2>11.1 Concrete rights</h2> <p>Technology governance should protect:</p> <ul><li>accessible interfaces and reasonable accommodation;</li> <li>freedom from discrimination based on disability, neurotype, communication style, distress, sensitivity, or unconventional affect;</li> <li>freedom from covert cognitive profiling and manipulation;</li> <li>the right to explanation and human review in consequential systems;</li> <li>the right to decline unnecessary biometric, behavioural, emotional, or neural inference;</li> <li>the right to use assistive and alternative interfaces;</li> <li>the right to disconnect where participation is not legally essential.</li></ul> <h2>11.2 No system-sanity authority</h2> <p>No panel, certification body, AI model, regulator, or platform may certify whether a person’s dissent, system criticism, distress, sensitivity, intelligence, or perception is “sane,” “accurate,” “honoured,” or developmentally superior.</p> <h2>11.3 No official cognitive environment</h2> <p>The framework does not mandate one set of alternative viewpoints, beliefs, moral narratives, or interpretations. Systems may support user-controlled diversity, source comparison, uncertainty, and contestability without selecting the worldview users must encounter.</p> <hr> <h1>12. Digital well-being and persuasive design</h1> <h2>12.1 Assessment objects</h2> <p>Digital-well-being review may examine:</p> <ul><li>deceptive or obstructive interface patterns;</li> <li>forced continuity, infinite scroll, autoplay, artificial urgency, and variable-reward design;</li> <li>covert personalization and emotional targeting;</li> <li>age-inappropriate persuasion;</li> <li>sleep, attention, social, or workplace pressures;</li> <li>user control over recommendations, notifications, ranking, timing, and data;</li> <li>accessibility and sensory load;</li> <li>dependency created by essential services or network effects.</li></ul> <h2>12.2 No universal psychological score</h2> <p>Well-being is plural and context-sensitive. The framework does not assign universal mental-health, social-cohesion, cognitive-affirmation, or happiness scores to technologies.</p> <h2>12.3 Protection rather than paternalism</h2> <p>Interventions should prioritize disclosure, user controls, defaults, age safeguards, interoperability, independent research access, and remedies for demonstrable harm. Compulsory restrictions require valid law and proportionality.</p> <hr> <h1>13. AI and automated-system governance interfaces</h1> <h2>13.1 Use-specific governance</h2> <p>AI governance follows the use and decision context. Medical, labour, education, public-benefit, judicial, scientific, media, infrastructure, and security uses do not share one residual regulator.</p> <h2>13.2 Automated-System Documentation Record</h2> <p>For consequential systems, documentation should include:</p> <ul><li>operator, provider, and controlling entities;</li> <li>intended and prohibited uses;</li> <li>model and system components;</li> <li>data and evaluation provenance;</li> <li>decision role and human responsibilities;</li> <li>affected populations and foreseeable misuse;</li> <li>performance across relevant groups and conditions;</li> <li>uncertainty, known failures, and out-of-distribution limits;</li> <li>security, monitoring, rollback, and decommissioning;</li> <li>contest, correction, and remedy routes.</li></ul> <h2>13.3 Prohibited automated authority</h2> <p>An automated system may not, by virtue of this framework, determine legal standing, guilt, detention, rights eligibility, Indigenous identity, mental sanity, political worth, consent, emergency status, moratorium, sanction, or redistribution.</p> <h2>13.4 Evaluation provenance</h2> <p>Benchmark selection, red-team design, evaluators, labels, scoring rules, model access, and excluded populations must be disclosed in the <strong>AI Evaluation Provenance Record</strong>.</p> <h2>13.5 Concentration and dependency</h2> <p>Assessments must examine compute concentration, cloud and chip dependencies, closed interfaces, model-owner leverage, public-sector lock-in, labour concentration, and the feasibility of migration or local operation.</p> <hr> <h1>14. Data and identity interface with Aurora Accord</h1> <p>All personal, relational, inferred, collective, Indigenous-restricted, evidentiary, ecological, confidential, security-sensitive, biometric, genetic, neural, and intimate data follow Aurora Accord.</p> <p>Technology Governance does not require:</p> <ul><li>a universal GGF identity;</li> <li>decentralized identifiers as the only identity architecture;</li> <li>a wallet, biometric, Love Ledger, Hearts, Leaves, or contribution credential;</li> <li>continuous telemetry for compliance;</li> <li>public AI-training dataset registries that expose protected data;</li> <li>immutable storage of personal or cultural content.</li></ul> <p>Technology records must support correction, lawful deletion, expiry, protected non-transfer, local custody, and equivalent offline processes.</p> <hr> <h1>15. Labour, maintenance, and technological transition</h1> <p>This section interfaces with <strong>Work in Liberation</strong> and applicable labour law. Technology Governance supplies use-specific evidence and transition records; it does not replace worker organization, collective bargaining, occupational safety, employment law, or adjudication.</p> <h2>15.1 Worker standing</h2> <p>Workers and their representatives have standing where technology affects hiring, scheduling, pay, workload, surveillance, safety, deskilling, job loss, professional judgment, or collective bargaining.</p> <h2>15.2 Algorithmic management</h2> <p>Employers must not use automation to evade wage, safety, accommodation, consultation, or collective-bargaining duties. Consequential workplace decisions require explanation, human responsibility, correction, and appeal under applicable labour law.</p> <h2>15.3 Maintenance as care work</h2> <p>Open-source and public-interest maintenance should receive stable funding, security support, documentation time, succession planning, and governance voice. Compensation must not depend on Love Ledger reputation, public contribution scoring, or ideological certification.</p> <h2>15.4 Transition continuity</h2> <p>Technology transitions must identify workers, communities, users, and essential services that depend on the existing system. Plans should include retraining, income continuity where authorized, migration support, data portability, procurement continuity, and safe decommissioning.</p> <hr> <h1>16. Lifecycle, ecological, and supply-chain responsibility</h1> <h2>16.1 Lifecycle profile</h2> <p>The <strong>Technology Lifecycle and Dependency Profile</strong> examines:</p> <ul><li>mineral extraction and land effects;</li> <li>energy and water use;</li> <li>hardware manufacture and labour;</li> <li>transport and data-centre infrastructure;</li> <li>operational emissions and cooling;</li> <li>repairability and software support;</li> <li>e-waste, recycling, and disposal;</li> <li>biodiversity and community impacts;</li> <li>supply-chain concentration and geopolitical risk;</li> <li>rebound effects and induced demand.</li></ul> <h2>16.2 Competent ecological authority</h2> <p>Ecological thresholds, permits, restoration orders, and liability derive from competent environmental and justice institutions. Technology assessors may provide evidence but do not create ecological jurisdiction.</p> <h2>16.3 Distributional accounting</h2> <p>Benefits and costs must be disaggregated by place, population, worker, generation, and ecosystem. A technology does not become regenerative merely because its total modeled benefits exceed total modeled costs.</p> <hr> <h1>17. Interoperability, portability, repair, and anti-lock-in</h1> <h2>17.1 Public-interest goals</h2> <p>The framework supports open interfaces, exportability, modular substitution, repair, documentation, accessible formats, and avoidance of unjustified vendor lock-in.</p> <h2>17.2 Lawful boundaries</h2> <p>Interoperability and repair do not authorize circumvention of legitimate safety, privacy, security, cultural, or evidentiary restrictions. Restrictions must be specific, reviewable, and no broader than necessary.</p> <h2>17.3 Equivalent implementation</h2> <p>Standards must permit equivalent local or sectoral implementations that satisfy the same outcome without requiring one vendor, protocol, cryptographic system, repository, or architecture.</p> <h2>17.4 Essential-service migration</h2> <p>Operators of essential systems must maintain migration, continuity, rollback, and data-return plans before dependency becomes irreversible.</p> <hr> <h1>18. Standards, certification, and accreditation</h1> <h2>18.1 Four distinct instruments</h2> <p>The framework distinguishes:</p> <ol><li><strong>voluntary standard</strong> — adopted by choice;</li> <li><strong>contractual requirement</strong> — binding only on parties to the contract;</li> <li><strong>public procurement condition</strong> — imposed by a competent purchaser within law;</li> <li><strong>legal requirement</strong> — adopted by a competent legislature or regulator.</li></ol> <p>Certification does not silently convert one instrument into another.</p> <h2>18.2 Certification scope</h2> <p>A certificate must state the product or use, version, operator, jurisdiction, evidence, exclusions, validity period, surveillance obligations, conflicts, and appeal route.</p> <h2>18.3 No rights gate</h2> <p>Loss or absence of certification may not remove fundamental access to justice, essential communication, healthcare, education, AUBI Layer 1, lawful employment protections, or other basic rights.</p> <h2>18.4 Independent accreditation</h2> <p>Accreditation and certification functions must be structurally independent of funding allocation, product development, enforcement, and adjudication.</p> <hr> <h1>19. Public-interest technology and stewardship forms</h1> <p>Technology may be held through public ownership, cooperative ownership, community trusts, stewardship trusts, commons, federations, non-profits, private firms, or mixed forms.</p> <p>No technology, model, codebase, dataset, patent, compute resource, or platform is converted into a trust or commons merely because a framework considers that form desirable. Conversion requires lawful acquisition, donation, purchase, licence, public-investment condition, antitrust remedy, insolvency process, or valid owner and community consent.</p> <p>The <strong>AI Asset and Stewardship Authority Record</strong> identifies ownership, licences, creditors, contributors, public funding, Indigenous and community claims, maintenance duties, governance, exit, fork rights, and dissolution.</p> <hr> <h1>20. Open-source software commons</h1> <h2>20.1 Federated repositories</h2> <p>GGF-supported software should use a federation of repositories and mirrors rather than a single canonical technical chokepoint. Projects retain clear maintainership, licence, governance, fork, archive, and succession rules.</p> <h2>20.2 Funding and maintenance</h2> <p>Public grants, procurement, membership contributions, service contracts, and other lawful mechanisms may fund maintenance. Funding decisions must disclose conflicts and must not depend on contribution reputation scores.</p> <h2>20.3 Security</h2> <p>Projects should implement risk-appropriate secure development, review, vulnerability disclosure, dependency management, release signing, incident response, and supported-version policies. Equivalent methods are permitted.</p> <h2>20.4 Fork and succession</h2> <p>Governance records must address maintainer exit, hostile takeover, abandoned dependencies, emergency forks, licence changes, trademark control, archives, and transfer of security credentials.</p> <hr> <h1>21. Public-interest and bioregional AI capacity</h1> <h2>21.1 Capital-efficient portfolio</h2> <p>The framework preserves a capital-efficient public-interest AI strategy using, where lawful and suitable:</p> <ul><li>open-weight or openly licensed backbones;</li> <li>continued pre-training on authorized local data;</li> <li>adapters and task-specific fine-tuning;</li> <li>retrieval-augmented systems;</li> <li>smaller and domain-specific models;</li> <li>shared regional compute and evaluation capacity;</li> <li>non-AI or lower-compute alternatives.</li></ul> <h2>21.2 Required safeguards</h2> <p>Each project must address:</p> <ul><li>model and software licences;</li> <li>data authority under Aurora;</li> <li>protected knowledge and Indigenous non-training restrictions;</li> <li>labour and compensation;</li> <li>security and misuse;</li> <li>energy, water, hardware, and supply-chain costs;</li> <li>language and cultural performance;</li> <li>evaluation independence;</li> <li>withdrawal, deletion, and retraining limits;</li> <li>operator responsibility and public-service continuity.</li></ul> <h2>21.3 Local adaptation is not local legitimacy</h2> <p>Regional training or curation does not by itself make a model democratically legitimate, safe, representative, or culturally authorized. The relevant public, professional, community, and Indigenous processes remain necessary.</p> <h2>21.4 No mandatory scaling</h2> <p>Projects may remain local, narrow, experimental, incompatible with global standards, or discontinued.</p> <hr> <h1>22. Cybersecurity and resilience interfaces</h1> <h2>22.1 Responsibility map</h2> <p>The <strong>Cyber Responsibility and System-Ownership Map</strong> distinguishes:</p> <ul><li>system owner and operator;</li> <li>software and infrastructure providers;</li> <li>data controller and processor;</li> <li>security operations and incident coordinator;</li> <li>critical-infrastructure authority;</li> <li>Aurora data supervisor;</li> <li>Conduit infrastructure continuity functions;</li> <li>Shield criminal or security investigation functions;</li> <li>Justice Systems warrant, evidence, adjudication, and remedy functions;</li> <li>affected communities and users.</li></ul> <h2>22.2 Risk-based outcomes</h2> <p>Security requirements should specify outcomes—confidentiality, integrity, availability, authentication, recoverability, logging, key management, vulnerability response, and continuity—rather than mandate one universal stack.</p> <h2>22.3 Community resilience</h2> <p>Local and community systems should receive resources for offline continuity, backups, secure communication, recovery exercises, accessible incident reporting, and independent support without requiring central telemetry.</p> <hr> <h1>23. Incident response and technology emergencies</h1> <h2>23.1 Incident state estimate</h2> <p>A suspected event produces a <strong>Technology Incident State Estimate</strong>, not an automatic legal emergency. The record distinguishes observed facts, hypotheses, affected systems, uncertainty, immediate risks, and competent authorities.</p> <h2>23.2 Operator containment</h2> <p>System owners may use pre-authorized technical controls within their ownership and contracts to isolate systems, revoke compromised credentials, disable vulnerable functions, or restore backups. Such action must be documented and limited to the operator’s lawful scope.</p> <h2>23.3 Public emergency authority</h2> <p>Compulsory public measures require a lawful emergency declaration or ordinary regulatory or judicial authority. The actor declaring or implementing an emergency cannot extend its own powers solely by internal vote.</p> <h2>23.4 Continuity and rights</h2> <p>Emergency measures must protect essential services, disability access, worker safety, evidence, personal data, Indigenous restrictions, legal challenge, and restoration to ordinary governance.</p> <h2>23.5 Layered disclosure</h2> <p>Incident communication should provide timely public accountability without publishing exploit details, protected data, security-sensitive infrastructure, or information that increases harm.</p> <hr> <h1>24. Intervention classes and circuit-breaker boundaries</h1> <p>“Circuit breaker” is not one power. The framework distinguishes:</p> <ol><li><strong>user control</strong> — a person disables or limits a system for themselves;</li> <li><strong>operator stop</strong> — the lawful operator pauses its own system;</li> <li><strong>contractual stop</strong> — authorized by a contract or procurement condition;</li> <li><strong>professional safety stop</strong> — exercised under professional or workplace authority;</li> <li><strong>regulatory order</strong> — issued under law;</li> <li><strong>judicial injunction</strong> — issued by a competent court or tribunal;</li> <li><strong>public advisory</strong> — non-binding warning;</li> <li><strong>legislative moratorium</strong> — enacted through valid law;</li> <li><strong>emergency measure</strong> — time-bounded action under valid emergency authority.</li></ol> <p>Every intervention must specify scope, evidence, authority, duration, affected parties, continuity, compensation where applicable, review, appeal, resumption, rollback, and post-action evaluation.</p> <p>Algorithms may recommend or execute pre-authorized technical safety controls. They may not independently create the authority, scope, or distributive consequences of compulsory intervention.</p> <hr> <h1>25. Justice, remedy, enforcement, and appeal</h1> <h2>25.1 Justice interface</h2> <p>Alleged harms, offences, liability, injunctions, compensation, sanctions, and model or product restrictions follow Justice Systems and applicable law.</p> <h2>25.2 Evidence custody</h2> <p>The <strong>Justice Referral and Evidence-Custody Record</strong> identifies provenance, collection authority, integrity, access, classified or protected material, personal and Indigenous data restrictions, expert interpretation, chain of custody, disclosure, and deletion or return.</p> <h2>25.3 Remedies</h2> <p>Depending on law, remedies may include correction, explanation, restoration, compensation, repair, accessibility, data return or deletion, contract adjustment, workplace remedy, licence restriction, injunction, recall, public notice, or institutional reform.</p> <h2>25.4 Appeal</h2> <p>Developers, operators, users, workers, communities, and other affected parties must have access to challenge proportionate to the consequence of the decision. Certification appeal is not a substitute for legal appeal.</p> <h2>25.5 No sanction by ecosystem exclusion</h2> <p>Loss of API access, interoperability, funds, trade access, or essential infrastructure is not an automatic response to framework non-alignment. Such consequences require a valid contractual, regulatory, judicial, procurement, or legislative basis and continuity safeguards.</p> <hr> <h1>26. Funding, procurement, and economic boundaries</h1> <h2>26.1 No self-authorized technology tax</h2> <p>The framework does not create an Automation Tax, Regenerative Tech Fund levy, global technology tax, or compulsory contribution. Public funding requires Treaty, budgetary, statutory, contractual, philanthropic, or other lawful authority.</p> <h2>26.2 No political or epistemic currency rewards</h2> <p>Hearts, Leaves, AUBI, or other material benefits must not depend on a technology being certified as regenerative, anti-parasitic, cognitively affirming, sane, or ideologically aligned.</p> <h2>26.3 Lawful public-investment tools</h2> <p>Competent institutions may use grants, procurement, challenge funds, public R&D, concessional finance, cooperative capital, prizes, shared infrastructure, and maintenance contracts. Each instrument must disclose selection criteria, conflicts, labour conditions, data claims, intellectual-property terms, public-return provisions, and failure outcomes.</p> <h2>26.4 Public procurement</h2> <p>The <strong>Public Procurement Technology Record</strong> specifies need, alternatives, authority, accessibility, security, interoperability, labour, lifecycle, data, vendor concentration, exit, continuity, and review.</p> <hr> <h1>27. Observation, records, dashboards, and protected non-transfer</h1> <h2>27.1 Layered transparency</h2> <p>Technology governance records may have:</p> <ul><li>public layers;</li> <li>participant or affected-party layers;</li> <li>supervisor or auditor layers;</li> <li>protected legal or security layers;</li> <li>Indigenous-restricted or community-controlled layers.</li></ul> <p>Transparency does not require total public visibility.</p> <h2>27.2 Dashboards</h2> <p>Dashboards display observations, definitions, uncertainty, missing data, correction history, and competing interpretations. They do not declare legitimacy, sanity, capture, consent, emergency, guilt, or legal compliance by themselves.</p> <h2>27.3 Protected non-transfer</h2> <p>Data, knowledge, model weights, vulnerability information, personal records, Indigenous materials, labour records, and security evidence may be subject to non-transfer, local custody, sealed access, purpose limitation, expiry, deletion, or return under Aurora and applicable law.</p> <h2>27.4 No default governance telemetry</h2> <p>Systems are not required to stream continuous behavioural, emotional, productivity, political, or cognitive telemetry to prove alignment.</p> <hr> <h1>28. Evaluation, learning, and anti-Goodhart safeguards</h1> <h2>28.1 Multidimensional evaluation</h2> <p>Evaluation may include:</p> <ul><li>access and exclusion;</li> <li>safety and rights;</li> <li>user and affected-party experience;</li> <li>worker and maintainer effects;</li> <li>ecological and supply-chain effects;</li> <li>security and recovery;</li> <li>concentration and dependency;</li> <li>interoperability and exit;</li> <li>false positives and false negatives;</li> <li>unexpected benefits and harms;</li> <li>distribution across populations and places.</li></ul> <h2>28.2 Anti-Goodhart rules</h2> <p>No single adoption, satisfaction, incident-response, FPIC, certification, “harm detected,” social-cohesion, or user-agreement target determines success.</p> <p>Evaluators must report gaming risks, selection effects, missing populations, perverse incentives, and whether the metric changed behaviour in ways that undermined the goal.</p> <h2>28.3 Failure Library</h2> <p>Pilots and institutions should publish lessons, limits, non-transferability, dissent, and negative outcomes while respecting confidentiality and protected non-transfer. Failure reporting must not compel a vulnerable community to disclose harm publicly.</p> <hr> <h1>29. Pilots, negotiation, adoption, and first seating</h1> <h2>29.1 Genesis alignment</h2> <p>Pre-Treaty work follows Genesis Protocol. Demonstrations may justify further research, negotiation, or voluntary adoption. They do not create jurisdiction or prove that a global council or standard is necessary.</p> <h2>29.2 Technology Pilot Constitutional Contract</h2> <p>Every pilot specifies:</p> <ul><li>host and legal authority;</li> <li>technology and governed use;</li> <li>participant rights and consent;</li> <li>affected-party standing;</li> <li>data and identity rules;</li> <li>labour and maintenance;</li> <li>ecological and infrastructure effects;</li> <li>security and incident response;</li> <li>evaluation questions and independence;</li> <li>complaint and remedy routes;</li> <li>refusal, withdrawal, migration, and wind-down;</li> <li>asset, code, model, and record disposition;</li> <li>prohibition on converting pilot participation into Treaty or regulatory consent.</li></ul> <h2>29.3 Independent readiness review</h2> <p>A readiness review may recommend whether to continue, narrow, redesign, negotiate, adopt locally, or stop. It cannot activate public authority.</p> <h2>29.4 First seating</h2> <p>Any standing Treaty technology institution must be created and seated under Treaty or a separately authorized protocol. v3.6 does not pre-seat a Global Technology Council.</p> <hr> <h1>30. Amendment, transfer, sunset, and dissolution</h1> <h2>30.1 Amendment</h2> <p>Before Treaty entry into force, voluntary procedures may be amended under their lawful charters. After entry into force, binding legal provisions follow the competent amendment process.</p> <h2>30.2 Sunset and review</h2> <p>Standards and programmes should have review dates appropriate to their risk and dependency. Sunset does not automatically terminate essential protections or services; continuity and migration must be planned.</p> <h2>30.3 Transfer</h2> <p>Transfer of models, repositories, standards, funds, data, credentials, contracts, or public programmes requires a <strong>Technology Transfer, Sunset, and Dissolution Record</strong>.</p> <h2>30.4 Dissolution and plural outcomes</h2> <p>A technology-governance body or programme may:</p> <ul><li>dissolve;</li> <li>narrow its mandate;</li> <li>transfer functions;</li> <li>federate;</li> <li>coexist with alternatives;</li> <li>retain a local scope;</li> <li>archive and cease operation;</li> <li>conclude that the proposed standard or institution should not exist.</li></ul> <p>There is no presumption of global scaling, harmonization, or reintegration.</p> <hr> <h1>31. Operational records and appendices</h1> <p>The following records operationalize the framework. They are templates, not self-executing authorities.</p> <h2>Appendix A — Technology Authority Provenance Record</h2> <p>Actor; authority source; jurisdiction; governed use; powers; prohibitions; affected parties; duration; review; appeal; continuity; expiry.</p> <h2>Appendix B — Governed Technology Use Description</h2> <p>Artefact; version; operator; controller; use; users; affected non-users; place; scale; duration; dependencies; alternatives; foreseeable misuse; withdrawal.</p> <h2>Appendix C — Technology Use, Dependency, and Impact Profile</h2> <p>Multidimensional assessment under Section 6; evidence; uncertainty; alternatives; distribution; unresolved risks; no composite legal score.</p> <h2>Appendix D — Technology State Estimate and Uncertainty Record</h2> <p>Observed facts; hypotheses; models; confidence; evidence conflicts; missing populations; update conditions; competing interpretations.</p> <h2>Appendix E — Assessment Independence and Conflict Map</h2> <p>Funders; assessors; operators; vendors; data sources; model providers; consultants; shared infrastructure; recusal; independent challenge.</p> <h2>Appendix F — Affected-Party Standing and Participation Record</h2> <p>Standing basis; notice; access; language; accommodation; representation; evidence; response; protection from retaliation; unresolved exclusions.</p> <h2>Appendix G — Community Technology Review Record</h2> <p>Community; lawful scope; affected use; benefits; harms; refusal; accessibility; labour; infrastructure; recommendation; dissent; follow-up.</p> <h2>Appendix H — Local Technology Sovereignty Charter</h2> <p>Local authority; systems covered; access; refusal; low-tech alternatives; data; procurement; interoperability; incident response; complaint; amendment; exit.</p> <h2>Appendix I — Indigenous Technology Interface and Non-Engagement Record</h2> <p>Affected people; authority identified by that people; consent/refusal/non-engagement; territory; law; knowledge; data; model training; benefit; remedy; protected non-transfer.</p> <h2>Appendix J — Accessibility and Cognitive Liberty Assessment</h2> <p>Disability access; neurodiversity; communication; sensory load; profiling; manipulation; explanation; human review; alternatives; discrimination; accommodation.</p> <h2>Appendix K — Persuasive and Digital Well-Being Design Record</h2> <p>Interface patterns; targeting; user controls; age safeguards; notification and ranking control; dependency; accessibility; evidence; uncertainty; mitigations.</p> <h2>Appendix L — Automated-System Documentation Record</h2> <p>System components; provider; operator; use; model; data; decision role; performance; limitations; security; monitoring; contest; rollback; decommissioning.</p> <h2>Appendix M — AI Evaluation Provenance Record</h2> <p>Benchmarks; labels; evaluators; populations; access; red-team methods; scoring; conflicts; missing tests; limitations; dissent.</p> <h2>Appendix N — AI Asset and Stewardship Authority Record</h2> <p>Ownership; licences; public funding; Indigenous/community claims; maintainers; governance; procurement; acquisition authority; fork; transfer; dissolution.</p> <h2>Appendix O — AI Training and Local Adaptation Record</h2> <p>Backbone; licence; data authority; protected knowledge; labour; compute; ecological impact; evaluation; security; withdrawal; unlearning or retraining limits.</p> <h2>Appendix P — Technology Labour and Maintenance Record</h2> <p>Workers; maintainers; employment status; pay; surveillance; bargaining; safety; workload; documentation; succession; transition; grievance.</p> <h2>Appendix Q — Technology Lifecycle and Dependency Profile</h2> <p>Materials; energy; water; hardware; labour; logistics; hosting; support; repair; e-waste; biodiversity; concentration; rebound; decommissioning.</p> <h2>Appendix R — Interoperability, Portability, and Repair Record</h2> <p>Interfaces; formats; export; shared and relational data; safety limits; repair documentation; equivalents; fees; migration; continuity; test results.</p> <h2>Appendix S — Standard Authority and Adoption Record</h2> <p>Standard owner; drafting process; evidence; instrument type; adopter; authority; jurisdiction; equivalents; review; versioning; withdrawal.</p> <h2>Appendix T — Certification Scope, Evidence, and Appeal Record</h2> <p>Certification body; accreditation; object; version; use; evidence; exclusions; conflicts; validity; surveillance; adverse decision; appeal; rights boundary.</p> <h2>Appendix U — Public Procurement Technology Record</h2> <p>Need; authority; alternatives; accessibility; data; security; labour; lifecycle; concentration; interoperability; exit; continuity; public-return terms.</p> <h2>Appendix V — Open-Source Commons Governance Record</h2> <p>Repositories; mirrors; licences; maintainers; decision rights; funding; security; release; fork; trademarks; succession; archive; dissolution.</p> <h2>Appendix W — Cyber Responsibility and System-Ownership Map</h2> <p>Owner; operator; providers; controllers; security roles; infrastructure authority; incident coordinator; regulator; Shield; Justice; affected users; handoffs.</p> <h2>Appendix X — Technology Incident State Estimate</h2> <p>Event; observations; hypotheses; systems; affected parties; severity; uncertainty; immediate protections; authorities; evidence; update schedule.</p> <h2>Appendix Y — Emergency Technology Coordination Record</h2> <p>Declaration source; lawful scope; coordinators; actions; prohibitions; rights; continuity; data; review; expiry; restoration; after-action review.</p> <h2>Appendix Z — Technology Intervention and Continuity Record</h2> <p>Intervention class; authority; evidence; scope; operator; affected parties; essential services; compensation; duration; appeal; resumption; rollback.</p> <h2>Appendix AA — Justice Referral and Evidence-Custody Record</h2> <p>Jurisdiction; alleged harm; collection authority; provenance; chain of custody; disclosure; protected material; expert interpretation; return/deletion; remedy route.</p> <h2>Appendix AB — Technology Funding and Conflict-of-Interest Record</h2> <p>Funding source; authority; selection; recipients; conflicts; procurement; IP; data claims; labour; public return; failure and clawback; audit.</p> <h2>Appendix AC — Technology Observation Contract</h2> <p>Decision; variables; sources; populations; missing data; limitations; frequency; access; correction; prohibited use; expiry.</p> <h2>Appendix AD — Technology Pilot Constitutional Contract</h2> <p>Host authority; scope; participants; rights; data; labour; ecological impact; security; evaluation; complaint; remedy; exit; wind-down; non-conversion into consent.</p> <h2>Appendix AE — Technology Transfer, Sunset, and Dissolution Record</h2> <p>Assets; code; models; data; credentials; contracts; funds; liabilities; users; workers; maintainers; archives; protected records; successor; final audit.</p> <h2>Appendix AF — Unresolved Risk and Non-Scaling Register</h2> <p>Unresolved risks; dissent; missing evidence; affected populations; rejected assumptions; local incompatibility; no-scale decision; review conditions.</p> <hr> <h1>Closing principle</h1> <p>Technology is world-building, but no framework is entitled to become the world’s builder.</p> <p>A legitimate technology-governance system protects the capacity to perceive, question, refuse, repair, adapt, and leave. It helps communities and competent authorities understand technological effects without turning one ethical vocabulary, psychological model, technical standard, or institutional centre into universal jurisdiction.</p> <blockquote><p><strong>The highest form of technological stewardship is not universal control. It is the preservation of plural, lawful, reversible ways of living with—and sometimes without—technology.</strong></p></blockquote>",1);function f(e){var i=r();n(792),o(e,i)}export{f as default,a as metadata};
